<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\Admin\RoomRequest; use App\Models\Room; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; class RoomController extends Controller { public function index(Request $request) { $rooms = Room::query()->when($request->filled("search"), function ($q) use ($request) { $s = $request->input("search"); $q->where(function ($x) use ($s) { $x->where("name","like","%".$s."%")->orWhere("building","like","%".$s."%")->orWhere("id","like","%".$s."%"); }); })->orderBy("id")->paginate(10)->withQueryString(); return view("admin.rooms.index",compact("rooms")); } public function create() { return view("admin.rooms.form",["room"=>new Room]); } public function store(RoomRequest $request) { Room::create($request->validated()); return redirect()->route("admin.rooms.index")->with("success","Kamar berhasil ditambahkan."); } public function edit(Room $room) { return view("admin.rooms.form",compact("room")); } public function update(RoomRequest $request, Room $room) { $room->update($request->validated()); return redirect()->route("admin.rooms.index")->with("success","Kamar berhasil diperbarui."); } public function destroy(Room $room) { $deleted = DB::transaction(function () use ($room) { $locked = Room::lockForUpdate()->findOrFail($room->id); if ($locked->bookings()->exists()) { return false; } $locked->favorites()->delete(); $locked->delete(); return true; }); if (!$deleted) { return back()->withErrors(["room"=>"Kamar memiliki riwayat pemesanan dan tidak dapat dihapus."]); } return redirect()->route("admin.rooms.index")->with("success","Kamar berhasil dihapus."); } }


